import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Игровая политика сервера","description":"","frontmatter":{"pageId":"admins/gameplay-policy","contentRevision":5},"headers":[],"relativePath":"ru/admins/gameplay-policy.md","filePath":"ru/admins/gameplay-policy.md"}'),o={name:"ru/admins/gameplay-policy.md"};function t(n,e,d,s,p,c){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="игровая-политика-сервера" tabindex="-1">Игровая политика сервера <a class="header-anchor" href="#игровая-политика-сервера" aria-label="Permalink to &quot;Игровая политика сервера&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>До открытия сервера объяви правила экономики, защиты новичков, рейдов, событий и хранения. Economy управляет лимитами посылок/лотов, комиссией, сбором хранения и запретом действий при угрозе. Raids задаёт число рейдеров, cooldown, добычу, мирный режим и сроки. Incidents включает каталог, очередь и цены. Live задаёт таймауты, паузы и ограничения потоков.</p><p>Integrity контролирует dev mode, изменение богатства и модификации сценария. Hygiene архивирует достаточно старые неактивные колонии при условиях богатства/возраста и определяет публичные диапазоны богатства. Отключение конкретной проверки требует понимания её значения, а не случайного нуля.</p><p>Для инцидента сначала заморозь нужную подсистему, сохрани id и аудит, изучи эскроу, затем отмени или разморозь. Проверяй возврат почтой.</p><h2 id="policy-example" tabindex="-1">Пример согласованного набора правил <a class="header-anchor" href="#policy-example" aria-label="Permalink to &quot;Пример согласованного набора правил {#policy-example}&quot;">​</a></h2><p>Перед стартом определи, разрешены ли рейды, как защищены новички/бедные цели, сколько времени занимает выход из peaceful и какие hostile-события доступны. Объясни игрокам различие real/copies и warned/instant. Не называй блокировку чата защитой от рейда.</p><p>Экономические правила должны раскрывать комиссию, платное хранение пешек/портящихся вещей, долг, ограничения при угрозе и распределение казны при роспуске. Поселение без online не симулируется сервером непрерывно. Зоны влияния — добровольный слой, не владение землёй. Эти границы важнее рекламного обещания «всё работает само».</p><h2 id="freeze-runbook" tabindex="-1">Заморозка подсистемы при инциденте <a class="header-anchor" href="#freeze-runbook" aria-label="Permalink to &quot;Заморозка подсистемы при инциденте {#freeze-runbook}&quot;">​</a></h2><p>Запиши время, игрока, id и состояние операции; включи freeze именно нужной подсистемы и сохрани audit. Проверь реальные кошельки/escrow/посылки и наличие ожидающего клиентского replay. Freeze не откатывает прошлые операции, а аукцион может ждать разрешения расчёта.</p><p>Выбери штатную отмену/возврат либо устранение причины. После действия проверь получателей и почту, затем сними freeze и наблюдай очередь. Не компенсируй серебром «на глаз»: автоматический возврат позднее создаст двойную выплату.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Константы аукционов, закупок, соцсистемы и влияния не обязательно конфигурируемы. Сбор хранения может создавать долг. Заморозка откладывает аукционный расчёт, не означает бесплатный возврат. Режим влияния не даёт территориальных прав.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./configuration">Справочник конфигурации</a></li><li><a href="./administration">Панель и модерация</a></li><li><a href="./../players/raids-incidents">Рейды и платные события</a></li></ul>',16)])])}const u=a(o,[["render",t]]);export{m as __pageData,u as default};
